# Reconstruct the three demonstrations' divider lattices and their cell interiors.
def mkgrid(h,w,bg,lc,rs,cs,nodes):
    g=[[bg]*w for _ in range(h)]
    for r in rs:
        for c in range(w): g[r][c]=lc
    for c in cs:
        for r in range(h): g[r][c]=lc
    for (r,c),v in nodes.items(): g[r][c]=v
    return g
# Demo 1
